tool_input.command:
databricks jobs create --json @- <<EOF
{
  "name": "${MLPAB_DATABRICKS_PREFIX}_create_table",
  "tasks": [
    {
      "task_key": "create_table",
      "sql_task": {
        "warehouse_id": "Starter Warehouse",
        "query": {
          "query_id": "$(databricks sql query create --data_source_id StarterWarehouse --query "$(cat create_table.sql)" --warehouse "Starter Warehouse" | jq -r .id)"
        }
      }
    }
  ]
}
EOF

